    "cellulitis",
    "erysipelas",
    "furuncle",
    "carbuncle",
    "boil",
    "MRSA",
    "community acquired MRSA",
    "Staphylococcus aureus",
    "Streptococcus pyogenes",
    "necrotising fasciitis",
    "LRINEC score",
    "Fournier gangrene",
    "breast abscess",
    "perianal abscess",
    "paronychia",
    "felon",
